import{assert}from"chrome://resources/js/assert.js";export function updateStructuredMetricsSummary(summaryBody,summary,template){summaryBody.replaceChildren();const enabled=buildKeyValueRow("Enabled",summary.enabled.toString(),template);summaryBody.append(enabled);const crosDeviceId=buildKeyValueRow("CrOS Device Id",summary.crosDeviceId||"-",template);summaryBody.append(crosDeviceId)}export function updateStructuredMetricsEvents(eventBody,events,eventTemplate,detailsTemplate,kvTemplate){eventBody.replaceChildren();for(const event of events){const row=eventTemplate.content.cloneNode(true);const[project,evn,type,uptime]=row.querySelectorAll("td");assert(project);project.textContent=event.project;assert(evn);evn.textContent=event.event;assert(type);type.textContent=event.type;assert(uptime);uptime.textContent=event.sequenceMetadata?.systemUptimeMs??"-";const detailsRow=detailsTemplate.content.cloneNode(true);const metricsRow=detailsRow.querySelector("#metrics-row");assert(metricsRow);const[details,metrics]=detailsRow.querySelectorAll("tbody");assert(details);assert(metrics);updateEventDetailsTable(details,event,kvTemplate);updateEventMetricsTable(metrics,event,kvTemplate);const eventRow=row.querySelector("#event-row");eventRow.addEventListener("click",(()=>{if(metricsRow.style.display==="none"){metricsRow.style.display="table-row"}else{metricsRow.style.display="none"}}),false);eventBody.append(row);eventBody.append(detailsRow)}}function updateEventDetailsTable(detailTable,event,template){detailTable.replaceChildren();const resetCounter=event.sequenceMetadata?.resetCounter??"-";const systemUptime=event.sequenceMetadata?.systemUptimeMs??"-";const eventId=event.sequenceMetadata?.id??"-";const resetCounterRow=buildKeyValueRow("Reset Id",resetCounter,template);const systemUptimeRow=buildKeyValueRow("System Uptime",systemUptime,template);const eventIdRow=buildKeyValueRow("Event Id",eventId,template);detailTable.append(resetCounterRow);detailTable.append(systemUptimeRow);detailTable.append(eventIdRow)}function updateEventMetricsTable(metricsTable,event,template){metricsTable.replaceChildren();for(const metric of event.metrics){const metricRow=buildKeyValueRow(metric.key,metric.value.toString(),template);metricsTable.append(metricRow)}}function buildKeyValueRow(key,value,template){const kvRow=template.content.cloneNode(true);const[k,v]=kvRow.querySelectorAll("td");assert(k);k.textContent=key;assert(v);v.textContent=value;return kvRow}